% Enums for categorical attributes
enum DIRECTION = {North, East, South, West};
enum TIME_MOMENT = {t1, t2, t3};

% Decision variables for the four cars
array[DIRECTION] of var 1..5: car_crossing_order;
array[DIRECTION] of var TIME_MOMENT: car_arrival_time;

% Decision variable for the pedestrian
var 1..5: pedestrian_crossing_order;
var TIME_MOMENT: pedestrian_arrival_time;

% Uniqueness: each crossing order position 1..5 used exactly once
constraint alldifferent([car_crossing_order[d] | d in DIRECTION] ++ [pedestrian_crossing_order]);

% Pedestrian-car interaction: pedestrian goes before East car
constraint pedestrian_crossing_order < car_crossing_order[East];

% Arrival-time-based ordering (with pedestrian-car interaction taking precedence)
% For cars vs pedestrian (except East car, already constrained above)
constraint forall(d in DIRECTION where d != East)(
  car_arrival_time[d] < pedestrian_arrival_time -> car_crossing_order[d] < pedestrian_crossing_order
);
constraint forall(d in DIRECTION where d != East)(
  car_arrival_time[d] > pedestrian_arrival_time -> car_crossing_order[d] > pedestrian_crossing_order
);

% For cars vs cars
constraint forall(d1, d2 in DIRECTION where d1 != d2)(
  car_arrival_time[d1] < car_arrival_time[d2] -> car_crossing_order[d1] < car_crossing_order[d2]
);

% Tie-breaking for simultaneous car arrivals: North < East < South < West (clockwise from North)
constraint forall(d1, d2 in DIRECTION where d1 != d2)(
  (car_arrival_time[d1] = car_arrival_time[d2] /\
   ((d1 = North /\ d2 in {East, South, West}) \/
    (d1 = East /\ d2 in {South, West}) \/
    (d1 = South /\ d2 = West)))
  -> car_crossing_order[d1] < car_crossing_order[d2]
);

% Specific arrival time facts
constraint pedestrian_arrival_time = t2;
constraint car_arrival_time[East] = t2;
constraint car_arrival_time[South] = t1;
constraint car_arrival_time[North] = t3;
constraint car_arrival_time[West] = t3;

solve satisfy;

