constraint arrivalTime_WestCar < arrivalTime_NorthCar -> crossingOrder_WestCar < crossingOrder_NorthCar;
constraint arrivalTime_WestCar < arrivalTime_SouthCar -> crossingOrder_WestCar < crossingOrder_SouthCar;
constraint arrivalTime_WestCar < arrivalTime_EastCar -> crossingOrder_WestCar < crossingOrder_EastCar;

% Clockwise right-of-way for simultaneous car arrivals: North, East, South, West
