include "globals.mzn";

% Entities: four cars and one pedestrian
enum CAR = {North, South, East, West};
enum ENTITY = {North_car, South_car, East_car, West_car, Pedestrian};

% Arrival times: we have three distinct time points based on the constraints
% Time 1: South car arrives
% Time 2: Pedestrian and East car arrive together
% Time 3: North car and West car arrive together
set of int: TIME = 1..3;

% Decision variables
array[ENTITY] of var TIME: arrival_time;
array[ENTITY] of var 1..5: passage_order;

% Arrival time assignments from specific scenario constraints
constraint arrival_time[South_car] = 1;
constraint arrival_time[Pedestrian] = 2;
constraint arrival_time[East_car] = 2;
constraint arrival_time[North_car] = 3;
constraint arrival_time[West_car] = 3;

% Global uniqueness: all passage orders different
constraint alldifferent(passage_order);

% Pedestrian goes before East car (rule 1 applied to eastern crosswalk)
constraint passage_order[Pedestrian] < passage_order[East_car];

% Rule 2: earlier arrival time implies earlier passage order
constraint forall(e1, e2 in ENTITY where e1 != e2)(
  arrival_time[e1] < arrival_time[e2] -> passage_order[e1] < passage_order[e2]
);

% Rule 3: tie-breaking among cars by clockwise order North, East, South, West
% Among cars with the same arrival time, apply clockwise priority
constraint forall(c1, c2 in CAR where c1 != c2)(
  let {
    var ENTITY: e1 = if c1 = North then North_car
                     elseif c1 = South then South_car
                     elseif c1 = East then East_car
                     else West_car endif,
    var ENTITY: e2 = if c2 = North then North_car
                     elseif c2 = South then South_car
                     elseif c2 = East then East_car
                     else West_car endif,
    int: priority1 = if c1 = North then 1
                     elseif c1 = East then 2
                     elseif c1 = South then 3
                     else 4 endif,
    int: priority2 = if c2 = North then 1
                     elseif c2 = East then 2
                     elseif c2 = South then 3
                     else 4 endif
  } in
  (arrival_time[e1] = arrival_time[e2] /\ priority1 < priority2) ->
    passage_order[e1] < passage_order[e2]
);

